def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            if value != 0:
                counts[value] = counts.get(value, 0) + 1

    background = max(counts, key=counts.get)
    object_colors = [color for color in counts if color != background]
    if not object_colors:
        return [row[:] for row in grid]
    color = min(object_colors, key=lambda x: counts[x])

    shape = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    min_r = min(r for r, c in shape)
    min_c = min(c for r, c in shape)
    shape = [(r - min_r, c - min_c) for r, c in shape]
    sh = max(r for r, c in shape) + 1
    sw = max(c for r, c in shape) + 1

    out = [row[:] for row in grid]
    for r0 in range(h - sh + 1):
        for c0 in range(w - sw + 1):
            cells = [(r0 + r, c0 + c) for r, c in shape]
            if all(grid[r][c] == 0 for r, c in cells):
                for r, c in cells:
                    out[r][c] = color
    return out
